$$\begin{aligned}
& \mathrm{K}_2 \mathrm{Cr}_2 \mathrm{O}_7(\mathrm{~s})+4 \mathrm{KCl}(\mathrm{s})+6 \mathrm{H}_2 \mathrm{SO}_4 \text { (conc.) } \\
& \rightarrow 2 \mathrm{CrO}_2 \mathrm{Cl}_2(\mathrm{~g})+6 \mathrm{KHSO}_4+3 \mathrm{H}_2 \mathrm{O}
